export interface RequestData {
    value: string;
    postId: string;
}
export interface ResponseData {
    resolvedValue: string;
}
export interface BatchRequestOptions {
    /**
     * An `AbortSignal` object instance; allows you to communicate with a request or abort it.
     */
    signal?: AbortSignal;
}
export interface RequestItem {
    /**
     * The ID of the batch where the request belongs to.
     */
    batchId: string;
    /**
     * The index of the request within a batch of requests.
     */
    requestIndex: number;
    /**
     * The index of the response within a batch of requests.
     */
    responseIndex: number;
}
